return [{
  json: {
    mensaje: 'Por ahora solo puedo leer mensajes de texto — ¿me escribes tu síntoma?'
  }
}];

// Detecta la especialidad comparando palabras clave contra el texto
// del paciente, en vez de depender del filtro nativo de Notion (que no
// puede matchear texto libre contra un título corto de la base
// 'Síntomas' — ver nota en 'Notion - Buscar Síntoma').
//
// PRIMERA VERSIÓN de palabras clave por especialidad: razonable pero
// no verificada contra las 5 filas reales de Notion — ajustar si falta
// algo. Nota: este nodo NO usa el contenido de las filas de Notion,
// solo el texto del paciente contra este diccionario fijo; si más
// adelante se quiere derivar las palabras clave directamente de la
// columna 'Síntoma' de cada fila, este es el lugar para hacerlo.

const sintomaOriginal = $('Telegram Trigger').item.json.message.text || '';

const textoNormalizado = sintomaOriginal
  .toLowerCase()
  .normalize('NFD')
  .replace(/[̀-ͯ]/g, '');

const KEYWORDS_POR_ESPECIALIDAD = {
  'Cardiología': ['pecho', 'corazon', 'palpitacion', 'palpitaciones', 'taquicardia'],
  'Gastroenterología': ['abdomen', 'abdominal', 'estomago', 'nausea', 'nauseas', 'vomito', 'diarrea'],
  'Traumatología': ['fractura', 'fracture', 'hueso', 'me cai', 'caida', 'esguince', 'torcedura'],
  'Neumología': ['respirar', 'respiracion', 'falta de aire', 'ahogo', 'pulmon', 'pulmones'],
  'Medicina General': ['fiebre', 'gripe', 'resfriado', 'cansancio', 'debilidad', 'malestar general']
};

let especialidadDetectada = null;
for (const [especialidad, keywords] of Object.entries(KEYWORDS_POR_ESPECIALIDAD)) {
  if (keywords.some(kw => textoNormalizado.includes(kw))) {
    especialidadDetectada = especialidad;
    break;
  }
}

// Mismo formato que 'Function - Evaluar Coincidencia' ya esperaba de
// Notion: { properties: { Especialidad: { select: { name } } } } si
// hay match, o un item vacío (json:{}) si no — igual que el patrón
// alwaysOutputData usado en el resto del workflow.
if (especialidadDetectada) {
  return [{
    json: {
      properties: {
        Especialidad: { select: { name: especialidadDetectada } }
      }
    }
  }];
}

return [{ json: {} }];

// Evalúa si la búsqueda en Notion encontró una especialidad válida
// Y extrae el plan (Premium/Básico) que el paciente menciona en su propio mensaje.
// No hay pre-registro de paciente: el plan viene siempre del texto.
const items = $input.all();
const huboError = items.some(item => item.json.error);
const especialidadEncontrada = !huboError && items.length > 0;

let especialidad = null;
if (especialidadEncontrada) {
  const props = items[0].json.properties || {};
  especialidad = props.Especialidad?.select?.name
    || props.Especialidad?.rich_text?.[0]?.plain_text
    || null;
}

const sintomaOriginal = $('Telegram Trigger').item.json.message.text;

// Normaliza (minúsculas, sin acentos) para detectar 'premium' / 'basico' sin importar mayúsculas o tildes.
const textoNormalizado = (sintomaOriginal || '')
  .toLowerCase()
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '');

let plan = null;
if (/\bpremium\b/.test(textoNormalizado)) {
  plan = 'Premium';
} else if (/\bbasico\b/.test(textoNormalizado)) {
  plan = 'Básico';
}

const especialidadFinal = especialidad !== null;
const planEncontrado = plan !== null;

const faltantes = [];
if (!especialidadFinal) faltantes.push('especialidad');
if (!planEncontrado) faltantes.push('plan');

return [{
  json: {
    especialidadEncontrada: especialidadFinal,
    especialidad,
    planEncontrado,
    plan,
    faltantes,
    sintomaOriginal,
    paso2Error: huboError
  }
}];

// Cálculo determinístico del copago y comparación de hospitales.
// Este cálculo se hace EXCLUSIVAMENTE aquí, en JavaScript puro.
// NUNCA se le pide a Groq (ni a ningún LLM) que calcule o compare montos:
// un LLM no es confiable para aritmética con dinero real.

// El nodo Notion de esta instancia usa el formato "Simplify" (activado por
// defecto, no configurado explícitamente en ningún nodo) — los items vienen
// con campos planos (property_hospital, property_costo_base, property_plan,
// property_especialidad, property_valor, property_tipo_de_regla), NO con la
// forma anidada properties.X.number/.select.name de la API cruda de Notion.

// El filtro combinado (Plan + Especialidad) de "Notion - Obtener Regla del
// Plan" NO se aplica en el servidor (confirmado en ejecución real: devuelve
// las 6 combinaciones Plan×Especialidad sin filtrar). Por eso este código
// filtra explícitamente por especialidad/plan, en vez de confiar en .first().

const especialidad = $('Function - Evaluar Coincidencia').first().json.especialidad;
const plan = $('Function - Evaluar Coincidencia').first().json.plan;

const hospitalesItems = $('Notion - Obtener Hospitales de la Red').all()
  .filter(item => item.json && item.json.property_hospital !== undefined)
  .filter(item => item.json.property_especialidad === especialidad);

const planItems = $('Notion - Obtener Regla del Plan').all()
  .filter(item => item.json && item.json.property_valor !== undefined);
const planItem = planItems.find(item =>
  item.json.property_plan === plan && item.json.property_especialidad === especialidad
);

const tipoDeRegla = planItem?.json?.property_tipo_de_regla ?? null;
const valorRegla = planItem?.json?.property_valor;

// Dato incompleto: NUNCA se asume un valor por defecto para la regla del plan.
// Se lanza un error explícito, que el IF de más abajo detecta y convierte
// en el mensaje de espera — no se calcula con un supuesto inventado.
if (typeof valorRegla !== 'number' || !tipoDeRegla) {
  throw new Error('No se encontró la regla del plan (Plan + Especialidad) en Notion. Dato incompleto, no se puede calcular el copago sin inventar un valor.');
}

if (hospitalesItems.length === 0) {
  throw new Error('No se encontraron hospitales para la especialidad encontrada.');
}

// El hospital más económico se elige SIEMPRE por costo base real, sin
// importar el tipo de regla del plan — es el hospital objetivamente más
// barato para esa especialidad.
const hospitalesOrdenados = hospitalesItems
  .map(item => ({
    nombre: item.json.property_hospital,
    costoBase: item.json.property_costo_base ?? 0
  }))
  .sort((a, b) => a.costoBase - b.costoBase);

const hospitalRecomendado = hospitalesOrdenados[0];

// El copago SÍ depende del tipo de regla:
// - "Monto fijo": el paciente paga ese monto exacto, sin importar el costo
//   base del hospital.
// - "Porcentaje": el paciente paga ese porcentaje del costo base del
//   hospital recomendado.
// Cualquier otro valor de "Tipo de regla" es un dato que no sabemos
// interpretar — no se asume nada, se trata como incompleto.
let copagoFinal;
if (tipoDeRegla === 'Monto fijo') {
  copagoFinal = valorRegla;
} else if (tipoDeRegla === 'Porcentaje') {
  copagoFinal = hospitalRecomendado.costoBase * (valorRegla / 100);
} else {
  throw new Error(`Tipo de regla desconocido: "${tipoDeRegla}". Valores esperados: "Monto fijo" o "Porcentaje". No se calcula el copago sin saber interpretarlo.`);
}

return [{
  json: {
    sintomaOriginal: $('Function - Evaluar Coincidencia').first().json.sintomaOriginal,
    especialidad,
    plan,
    tipoDeRegla,
    valorRegla,
    hospitales: hospitalesOrdenados,
    hospitalRecomendado,
    copagoFinal
  }
}];

